import{createClient}from'https://esm.sh/@supabase/supabase-js@2.57.0';const S=createClient('https://zdmpcvlmjmsapydaljms.supabase.co','sb_publishable_eGELBhmMhdPu4g4Sw5g2xg_3oO7g8ib',{auth:{persistSession:true,autoRefreshToken:true}}),E='https://zdmpcvlmjmsapydaljms.supabase.co/functions/v1/private-admin-v2';let session=null;const $=id=>document.getElementById(id),msg=(x,err=false)=>{const e=$('msg');e.textContent=x;e.className=err?'error':''};async function api(path,opts={}){const r=await fetch(E+'/'+path,{...opts,headers:{'Content-Type':'application/json',...(session?{Authorization:'Bearer '+session.access_token}:{})}});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}$('lf').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),station=String(f.get('station')).trim().toLowerCase(),code=String(f.get('code')).trim().toLowerCase(),password=String(f.get('password'));try{const q=await S.auth.signInWithPassword({email:`${code}@${station}.fuelpulse.local`,password});if(q.error)throw q.error;session=q.data.session;await load();$('login').classList.add('hidden');$('app').classList.remove('hidden');msg('');}catch(x){msg(x.message||String(x),true)}};async function load(){const rows=await api('organizations');$('orgs').innerHTML=rows.map(x=>`<div class="cred"><span>${x.name}<small class="muted"> ${x.slug}</small></span><b>${new Date(x.created_at).toLocaleDateString('en-IN')}</b></div>`).join('')||'No organizations yet.'}$('of').onsubmit=async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));try{const d=await api('owners',{method:'POST',body:JSON.stringify(b)});$('result').classList.remove('hidden');$('result').innerHTML=`<h2>Owner created</h2><p class="muted">Save these credentials now. The generated password is shown only here.</p><div class="cred"><span>Station ID</span><b>${d.station_slug}</b><button data-copy="${d.station_slug}">Copy</button></div><div class="cred"><span>Owner code</span><b>${d.owner_code}</b><button data-copy="${d.owner_code}">Copy</button></div><div class="cred"><span>Temporary password</span><b>${d.ownerPassword}</b><button data-copy="${d.ownerPassword}">Copy</button></div>`;$('result').querySelectorAll('[data-copy]').forEach(b=>b.onclick=()=>navigator.clipboard.writeText(b.dataset.copy));e.currentTarget.reset();await load()}catch(x){$('result').classList.remove('hidden');$('result').innerHTML=`<p class="error">${x.message||x}</p>`}};$('logout').onclick=async()=>{await S.auth.signOut();session=null;$('app').classList.add('hidden');$('login').classList.remove('hidden')};